import fs from 'node:fs'

const fullKjv = JSON.parse(fs.readFileSync('/tmp/opencode/kjv_es.json', 'utf8'))
const PEOPLE = JSON.parse(fs.readFileSync('/tmp/opencode/bt/people.json', 'utf8'))
const PLACES = JSON.parse(fs.readFileSync('/tmp/opencode/bt/places.json', 'utf8'))
const EVENTS = JSON.parse(fs.readFileSync('/tmp/opencode/bt/events.json', 'utf8'))
const BOOKS = JSON.parse(fs.readFileSync('/tmp/opencode/bt/books.json', 'utf8'))

const BOOK_NAME_BY_ID = new Map(BOOKS.map((b) => [b.id, b.name]))
const BOOK_ID_BY_NAME = new Map(BOOKS.map((b) => [b.name, b.id]))
for (const b of fullKjv) BOOK_ID_BY_NAME.set(b.name, b.name)
// normalize canonical names to fullKjv names
const canonical = (name) => name.replace('Psalm', 'Psalms').replace('Song of Songs', 'Song of Solomon')
for (const name of Object.keys(Object.fromEntries(BOOK_ID_BY_NAME))) {
  const c = canonical(name)
  if (c !== name) BOOK_ID_BY_NAME.set(name, c)
}

function parseReference(ref) {
  const parts = ref.split(/[;,]/).map((s) => s.trim()).filter(Boolean)
  const ranges = []
  for (const part of parts) {
    const m = part.match(/^((?:[1-3]\s+)?[A-Za-z][A-Za-z ]*?)\s+(\d+)(?::(\d+)(?:\s*-\s*(?:(\d+):)?(\d+))?)?(?:\s*-\s*(\d+))?$/)
    if (!m) { console.error('unparsed ref', part); continue }
    const book = canonical(m[1].trim())
    const chapter = Number(m[2])
    let start = m[3] ? Number(m[3]) : null
    let end = start
    if (m[5]) { end = Number(m[5]); if (m[4]) { /* cross-chapter range */ } }
    else if (m[6]) { end = Number(m[6]) }
    if (start === null) { start = 1; end = null }
    if (end === null) end = null
    ranges.push({ book, chapter, start, end })
  }
  return ranges
}

const verses = []
for (const book of fullKjv) {
  book.chapters.forEach((chapter, ci) => {
    chapter.forEach((text, vi) => {
      verses.push({ book: canonical(book.name), chapter: ci + 1, verse: vi + 1, text })
    })
  })
}
const verseKey = (v) => `${v.book} ${v.chapter}:${v.verse}`

function versesForEvent(event) {
  const ranges = parseReference(event.reference)
  const out = []
  for (const r of ranges) {
    for (const v of verses) {
      if (v.book !== r.book || v.chapter !== r.chapter) continue
      if (r.start !== null && v.verse < r.start) continue
      if (r.end !== null && v.verse > r.end) continue
      out.push(v)
    }
  }
  return out
}

const EVENT_BY_ID = new Map(EVENTS.map((e) => [e.id, e]))
const EVENT_BY_NAME = new Map(EVENTS.map((e) => [e.name, e]))
const PERSON_BY_ID = new Map(PEOPLE.map((p) => [p.id, p]))
const PLACE_BY_ID = new Map(PLACES.map((p) => [p.id, p]))

const STOP = new Set(`a an the and or but if then than that this these those of to in on at by for from with into unto upon out up down over under through between among against after before as so not no nor yet also even just only very may might can could would should shall will do did done does been being is are was were be have hath has had thee thou thy thine ye you your he she it they them their his her him we us our i my me mine who whom whose which what when where why how there here all any every each both few more most much many some such own same other another said saith saying spake speak speaketh went came come cometh go goeth make maketh made take taketh took give giveth gave know knoweth knew see seeth saw look behold wherefore therefore thereof therein thereby whereby wherein whereof whosoever whatsoever again ever never yes nor still well even now also thus then thither hither whither hence whence peradventure notwithstanding nevertheless moreover furthermore howbeit albeit although though while whilst until till since because unless whether either neither both each every all any some none one two three four five six seven eight nine ten first second third fourth fifth sixth seventh eighth ninth tenth eleven twelve twenty thirty forty fifty hundred thousand according also among`.split(/\s+/))

function tokens(text) {
  return [...text.toLowerCase().matchAll(/[a-z]+(?:'[a-z]+)?/g)].map((m) => m[0]).filter((w) => w.length > 3 && !STOP.has(w))
}

