function scoreVerse(v, entity, { nameTokens = [], upEventIds = [] } = {}) {
  const text = v.text.toLowerCase()
  const wordSet = new Set(tokens(v.text))
  let score = 0
  if (nameTokens.some((n) => text.includes(n.toLowerCase()))) score += 30
  const entityTokens = tokens(entity.summary || entity.deed || entity.clue || entity.significance || '')
  const unique = [...new Set(entityTokens)]
  for (const t of unique) if (wordSet.has(t)) score += 3
  // reward longer / more specific entity text matches
  for (const phrase of (entity.keywords || [])) if (text.includes(phrase.toLowerCase())) score += 4
  return score
}

function chooseVerse(candidates, entity, nameTokens) {
  const scored = candidates.map((v) => ({ v, score: scoreVerse(v, entity, { nameTokens }) }))
  scored.sort((a, b) => b.score - a.score || a.v.chapter - b.v.chapter || a.v.verse - b.v.verse)
  return scored[0]
}

function getNameTokens(name) {
  const norm = name.toLowerCase().replace(/[^a-z]/g, ' ')
  const base = norm.split(/\s+/).filter((w) => w.length > 2 && !['the', 'son', 'of', 'mount', 'region', 'river', 'sea', 'valley', 'garden'].includes(w))
  return base
}

function candidateVersesForPerson(person) {
  const up = PERSON_BY_ID.get(person.id)
  if (!up) return []
  const seen = new Set()
  const out = []
  for (const eventId of up.events || []) {
    const e = EVENT_BY_ID.get(eventId)
    if (!e) continue
    for (const v of versesForEvent(e)) {
      const k = verseKey(v)
      if (!seen.has(k)) { seen.add(k); out.push(v) }
    }
  }
  return out
}

function candidateVersesForPlace(place) {
  const up = PLACE_BY_ID.get(place.id)
  if (!up) return []
  const seen = new Set()
  const out = []
  for (const eventId of up.events || []) {
    const e = EVENT_BY_ID.get(eventId)
