    for (const v of versesForEvent(e)) {
      const k = verseKey(v)
      if (!seen.has(k)) { seen.add(k); out.push(v) }
    }
  }
  return out
}

function candidateVersesForEvent(event) {
  const up = EVENT_BY_NAME.get(event.name)
  if (!up) return []
  return versesForEvent(up)
}

