const PLACES = JSON.parse(fs.readFileSync('/tmp/opencode/bt/places.json', 'utf8'))
const EVENTS = JSON.parse(fs.readFileSync('/tmp/opencode/bt/events.json', 'utf8'))

const BOOK_NAMES = fullKjv.map((b) => b.name)
const BOOK_SET = new Set(BOOK_NAMES)
const canonicalBook = (name) => {
  const n = name.trim().replace(/^Psalm\b/, 'Psalms').replace(/^Song of Songs$/, 'Song of Solomon')
  if (BOOK_SET.has(n)) return n
  return n
}

function parseReference(ref) {
  const parts = ref.split(';').map((s) => s.trim()).filter(Boolean)
  const ranges = []
  for (const part of parts) {
    // split comma-separated subranges belonging to same book, e.g. Genesis 1:1, 2:3
    const pieces = part.split(',').map((s) => s.trim())
    let previousBook = null
    for (const piece of pieces) {
      const m = piece.match(/^((?:[1-3]\s+)?[A-Za-z][A-Za-z ]*?)\s+(\d+)(?::(\d+))?(?:\s*[-–]\s*(?:(\d+):)?(\d+))?$/)
      if (!m) { console.error('unparsed ref piece', piece, 'from', ref); continue }
      const book = canonicalBook(m[1])
      previousBook = book
      const chapter = Number(m[2])
      const start = m[3] ? Number(m[3]) : 1
      let endChapter = chapter
      let end = start
      if (m[5]) {
        end = Number(m[5])
        if (m[4]) endChapter = Number(m[4])
      }
      ranges.push({ book, startChapter: chapter, startVerse: start, endChapter, endVerse: end })
    }
  }
  return ranges
}

const verses = []
for (const book of fullKjv) {
  book.chapters.forEach((chapter, ci) => {
    chapter.forEach((text, vi) => {
      verses.push({ book: canonicalBook(book.name), chapter: ci + 1, verse: vi + 1, text })
    })
  })
}
const verseKey = (v) => `${v.book} ${v.chapter}:${v.verse}`

function verseInRange(v, r) {
  if (v.book !== r.book) return false
  if (v.chapter < r.startChapter || v.chapter > r.endChapter) return false
  if (v.chapter === r.startChapter && v.verse < r.startVerse) return false
  if (v.chapter === r.endChapter && v.verse > r.endVerse) return false
  return true
}

function versesForReference(ref) {
  const ranges = parseReference(ref)
  return verses.filter((v) => ranges.some((r) => verseInRange(v, r)))
}

