const PLACE_BY_ID = new Map(PLACES.map((p) => [p.id, p]))

const STOP = new Set(`a an the and or but if then than that this these those of to in on at by for from with into unto upon out up down over under through between among against after before as so not no nor yet also even just only very may might can could would should shall will do did done does been being is are was were be have hath has had thee thou thy thine ye you your he she it they them their his her him we us our i my me mine who whom whose which what when where why how there here all any every each both few more most much many some such own same other another said saith saying spake speak speaketh went came come cometh go goeth make maketh made take taketh took give giveth gave know knoweth knew see seeth saw look behold wherefore therefore thereof therein thereby whereby wherein whereof whosoever whatsoever again ever never yes nor still well even now also thus then thither hither whither hence whence peradventure notwithstanding nevertheless moreover furthermore howbeit albeit although though while whilst until till since because unless whether either neither both each every all any some none one two three four five six seven eight nine ten first second third fourth fifth sixth seventh eighth ninth tenth eleven twelve twenty thirty forty fifty hundred thousand according`.split(/\s+/))

function tokens(text) {
  return [...text.toLowerCase().matchAll(/[a-z]+(?:'[a-z]+)?/g)].map((m) => m[0]).filter((w) => w.length > 3 && !STOP.has(w))
}

// Document frequency for IDF weighting
const df = new Map()
for (const v of verses) {
  for (const t of new Set(tokens(v.text))) df.set(t, (df.get(t) || 0) + 1)
}
const N = verses.length
const idf = (t) => Math.log(N / ((df.get(t) || 1) + 1))

