function getNameTokens(name) {
  const norm = name.toLowerCase().replace(/[^a-z]/g, ' ')
  return norm.split(/\s+/).filter((w) => w.length > 2 && !['the', 'son', 'of', 'mount', 'region', 'river', 'sea', 'valley', 'garden', 'great', 'apostle', 'evangelist', 'priest', 'brother'].includes(w))
}

function nameVariants(entity) {
  return [...new Set([...(NAME_VARIANTS[entity.name] || []), ...getNameTokens(entity.name), ...(PERSON_ALIASES[entity.id] || [])])]
}

function normalize(text) {
  return text.toLowerCase().replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ')
}

function scoreVerse(v, entity, variants) {
  const text = normalize(v.text)
  const wordSet = new Set(tokens(v.text))
  let score = 0
  let nameHits = 0
  for (const n of variants) {
    if (!n) continue
    if (text.includes(normalize(n))) nameHits += 1
  }
  score += nameHits * 60
  const summaryTokens = [...new Set(tokens(entity.summary || entity.deed || entity.clue || entity.significance || ''))]
  for (const t of summaryTokens) {
    if (wordSet.has(t)) score += Math.min(8, idf(t))
  }
  for (const phrase of entity.keywords || []) {
    if (text.includes(normalize(phrase))) score += 6
  }
  return { score, nameHits }
}

function choose(candidates, entity) {
  const variants = nameVariants(entity)
  const scored = candidates.map((v) => ({ v, ...scoreVerse(v, entity, variants) }))
  scored.sort((a, b) => b.score - a.score || b.nameHits - a.nameHits || a.v.chapter - b.v.chapter || a.v.verse - b.v.verse)
  return scored
}

function eventVersesFor(ids) {
  const seen = new Set()
  const out = []
  for (const id of ids || []) {
    const e = EVENT_BY_ID.get(id)
    if (!e) continue
    for (const v of versesForReference(e.reference)) {
      const k = verseKey(v)
      if (!seen.has(k)) { seen.add(k); out.push(v) }
    }
  }
  return out
}

function candidatesForPerson(p) {
  const up = PERSON_BY_ID.get(p.id)
  const fromEvents = up ? eventVersesFor(up.events) : []
  const variants = nameVariants(p)
  const nameHits = verses.filter((v) => variants.some((n) => normalize(v.text).includes(normalize(n))))
  const all = [...fromEvents]
  const seen = new Set(all.map(verseKey))
  for (const v of nameHits) if (!seen.has(verseKey(v))) { seen.add(verseKey(v)); all.push(v) }
  return all
}

function candidatesForPlace(p) {
  const up = PLACE_BY_ID.get(p.id)
  const fromEvents = up ? eventVersesFor(up.events) : []
  const variants = nameVariants(p)
  const nameHits = verses.filter((v) => variants.some((n) => normalize(v.text).includes(normalize(n))))
  const all = [...fromEvents]
  const seen = new Set(all.map(verseKey))
  for (const v of nameHits) if (!seen.has(verseKey(v))) { seen.add(verseKey(v)); all.push(v) }
  return all
}

function candidatesForEvent(e) {
  const up = EVENT_BY_NAME.get(e.name)
  return up ? versesForReference(up.reference) : []
}

