function eventText(e) {
  return [e.name, e.summary, ...(e.keywords || []), ...(e.mainPeople || []), ...(e.relatedPeople || []), ...(e.relatedPlaces || [])].join(' ')
}

function eventScore(e, entity) {
  const words = new Set(tokens(eventText(e)))
  const summaryTokens = [...new Set(tokens(entity.summary || entity.deed || entity.clue || entity.significance || ''))]
  let score = 0
  for (const t of summaryTokens) if (words.has(t)) score += Math.min(10, idf(t) * 2)
  const text = normalize(eventText(e))
  for (const phrase of entity.keywords || []) if (text.includes(normalize(phrase))) score += 4
  if ((e.mainPeople || []).includes(entity.id)) score += 8
  if ((e.relatedPeople || []).includes(entity.id)) score += 3
  if ((e.location?.placeId || '') === entity.id) score += 8
  return score
}

function scoreVerse(v, entity, variants) {
  const text = normalize(v.text)
  const wordSet = new Set(tokens(v.text))
  let score = 0
  let nameHits = 0
  for (const n of variants) if (n && text.includes(normalize(n))) nameHits += 1
  score += nameHits * 50
  const summaryTokens = [...new Set(tokens(entity.summary || entity.deed || entity.clue || entity.significance || ''))]
  for (const t of summaryTokens) if (wordSet.has(t)) score += Math.min(10, idf(t))
  for (const phrase of entity.keywords || []) if (text.includes(normalize(phrase))) score += 6
  return { score, nameHits }
}

function eventChoicesFor(entity) {
  const up = entity.kind === 'person' ? PERSON_BY_ID.get(entity.id) : PLACE_BY_ID.get(entity.id)
  if (!up) return []
  return (up.events || []).map((id) => EVENT_BY_ID.get(id)).filter(Boolean)
    .map((e) => ({ e, score: eventScore(e, entity) }))
    .sort((a, b) => b.score - a.score)
}

function chooseVerseInEvent(e, entity) {
  const candidates = versesForReference(e.reference)
  const variants = nameVariants(entity)
  const ranked = candidates.map((v) => ({ v, ...scoreVerse(v, entity, variants) }))
  ranked.sort((a, b) => b.score - a.score || a.v.chapter - b.v.chapter || a.v.verse - b.v.verse)
  return ranked
}

