import fs from 'node:fs'

const fullKjv = JSON.parse(fs.readFileSync('/tmp/opencode/kjv_es.json', 'utf8'))
const finalRefs = JSON.parse(fs.readFileSync('/tmp/opencode/final-refs.json', 'utf8'))
const textUpdates = JSON.parse(fs.readFileSync('/tmp/opencode/text-updates.json', 'utf8'))

const canonicalBook = (name) => name.trim().replace(/^Psalm\b/, 'Psalms').replace(/^Song of Songs$/, 'Song of Solomon')
const books = new Map(fullKjv.map((b) => [canonicalBook(b.name), b]))

function parseReference(ref) {
  const parts = ref.split(';').map((s) => s.trim()).filter(Boolean)
  const ranges = []
  for (const part of parts) {
    const pieces = part.split(',').map((s) => s.trim())
    let previousBook = null
    for (const piece of pieces) {
      let m = piece.match(/^((?:[1-3]\s+)?[A-Za-z][A-Za-z ]*?)\s+(\d+)(?::(\d+))?(?:\s*[-–]\s*(?:(\d+):)?(\d+))?$/)
      let book, chapter, start, endChapter, end
      if (m) {
        book = canonicalBook(m[1]); chapter = Number(m[2]); start = m[3] ? Number(m[3]) : 1
        endChapter = chapter; end = m[5] ? Number(m[5]) : (m[3] ? start : 999)
        if (m[4]) endChapter = Number(m[4])
      } else {
        m = piece.match(/^(\d+)(?::(\d+))?(?:\s*[-–]\s*(?:(\d+):)?(\d+))?$/)
        if (!m || !previousBook) throw new Error(`Cannot parse reference piece: ${piece} in ${ref}`)
        book = previousBook; chapter = Number(m[1]); start = m[2] ? Number(m[2]) : 1
        endChapter = m[4] ? Number(m[4]) : chapter; end = m[5] ? Number(m[5]) : (m[2] ? start : 999)
      }
      previousBook = book
      ranges.push({ book, startChapter: chapter, startVerse: start, endChapter, endVerse: end })
    }
  }
  return ranges
}

function versesForReference(ref) {
  const ranges = parseReference(ref)
  const out = []
  for (const r of ranges) {
    const book = books.get(r.book)
    if (!book) throw new Error(`Unknown book ${r.book} in ${ref}`)
    for (let c = r.startChapter; c <= r.endChapter; c += 1) {
      const chapter = book.chapters[c - 1]
      if (!chapter) throw new Error(`Missing chapter ${r.book} ${c} in ${ref}`)
      const start = c === r.startChapter ? r.startVerse : 1
      const end = c === r.endChapter ? Math.min(r.endVerse, chapter.length) : chapter.length
      for (let v = start; v <= end; v += 1) {
        const text = chapter[v - 1]
        if (!text) throw new Error(`Missing verse ${r.book} ${c}:${v} in ${ref}`)
        out.push({ book: r.book, chapter: c, verse: v, text })
      }
    }
  }
  return out
}

function buildVerse(ref) {
  const seen = new Set()
  const texts = []
  for (const v of versesForReference(ref)) {
    const key = `${v.book} ${v.chapter}:${v.verse}`
    if (seen.has(key)) continue
    seen.add(key)
    texts.push(v.text)
  }
  return texts.join(' ')
}

const file = '/home/runner/work/PlayGround/PlayGround/src/data/activities.js'
let source = fs.readFileSync(file, 'utf8')

function findObjectBounds(id, arrayName) {
  const arrayStart = source.indexOf(`export const ${arrayName} = [`)
  if (arrayStart < 0) throw new Error(`Array ${arrayName} not found`)
  const arrayEnd = source.indexOf('\n]', arrayStart)
  if (arrayEnd < 0) throw new Error(`Array end ${arrayName} not found`)
  const marker = `{\n    "id": "${id}",`
  const start = source.indexOf(marker, arrayStart)
  if (start < 0 || start > arrayEnd) throw new Error(`Object ${id} not found in ${arrayName}`)
  let depth = 0
  let inString = false
  let escaped = false
  for (let i = start; i < source.length; i += 1) {
    const ch = source[i]
    if (inString) {
      if (escaped) escaped = false
      else if (ch === '\\') escaped = true
      else if (ch === '"') inString = false
      continue
    }
    if (ch === '"') { inString = true; continue }
    if (ch === '{') depth += 1
    else if (ch === '}') {
      depth -= 1
      if (depth === 0) return { start, end: i + 1 }
    }
  }
  throw new Error(`Unclosed object ${id}`)
}

function replaceField(objectText, field, value) {
  const pattern = new RegExp(`("${field}":\\s*)"(?:[^"\\\\]|\\\\.)*"`)
  if (!pattern.test(objectText)) throw new Error(`Field ${field} not found`)
  return objectText.replace(pattern, `$1${JSON.stringify(value)}`)
}

const groupDefs = [
  ['PEOPLE', 'people'],
  ['PLACES', 'places'],
  ['EVENTS', 'events'],
]
const report = []
for (const [arrayName, group] of groupDefs) {
  for (const [id, item] of Object.entries(finalRefs[group])) {
    const ref = item.reference
    if (!ref) continue
    const verse = buildVerse(ref)
    const bounds = findObjectBounds(id, arrayName)
    let objectText = source.slice(bounds.start, bounds.end)
    objectText = replaceField(objectText, 'reference', ref)
    objectText = replaceField(objectText, 'verse', verse)
    const updates = textUpdates[group]?.[id]
    if (updates) {
      for (const field of ['deed', 'clue', 'riddle', 'summary']) {
        if (updates[field]) objectText = replaceField(objectText, field, updates[field])
      }
    }
    source = source.slice(0, bounds.start) + objectText + source.slice(bounds.end)
    report.push({ group, id, name: item.name, reference: ref, verse })
  }
}

fs.writeFileSync(file, source)
fs.writeFileSync('/tmp/opencode/verse-report.json', JSON.stringify(report, null, 2))
console.log(`updated ${report.length} activity records`)

