import fs from 'node:fs'

const KJV = JSON.parse(fs.readFileSync('/tmp/opencode/kjv_es.json', 'utf8'))
const bookByName = new Map(KJV.map((book) => [book.name, book]))
const aliases = new Map([
  ['Psalm', 'Psalms'],
  ['Song of Songs', 'Song of Solomon'],
])
bookByName.set('Psalm', bookByName.get('Psalms'))
bookByName.set('Song of Songs', bookByName.get('Song of Solomon'))

export function getVerse(bookName, chapter, verse) {
  const book = bookByName.get(aliases.get(bookName) || bookName)
  if (!book) throw new Error(`Unknown book: ${bookName}`)
  const text = book.chapters[chapter - 1]?.[verse - 1]
  if (!text) throw new Error(`Unknown verse: ${bookName} ${chapter}:${verse}`)
  return text
}

export function parseRef(ref) {
  const match = ref.trim().match(/^(.+?)\s+(\d+):(\d+)(?:-(\d+))?$/)
  if (!match) throw new Error(`Bad reference: ${ref}`)
  const [, book, chapter, start, end] = match
  return { book, chapter: Number(chapter), start: Number(start), end: Number(end || start) }
}

export function getRefText(ref) {
  const { book, chapter, start, end } = parseRef(ref)
  return Array.from({ length: end - start + 1 }, (_, index) => getVerse(book, chapter, start + index)).join(' ')
}

export function getCompositeText(reference) {
  return reference.split(';').map((part) => getRefText(part.trim())).join(' ')
}

if (process.argv[1] === new URL(import.meta.url).pathname) {
  const ref = process.argv[2]
  if (!ref) {
    console.error('Usage: node kjv-helper.mjs "Genesis 1:1"')
    process.exit(1)
  }
  console.log(getCompositeText(ref))
}

