  const o=await import('/tmp/opencode/activities-old.js');
  const n=await import('/tmp/opencode/activities-new.js');
  let issues=0;
  for (const g of Object.keys(o)) {
    const om=new Map(o[g].map(x=>[x.id,x]));
    for (const x of n[g]) {
      const a=om.get(x.id);
      if(!a){ console.log('NEW RECORD',g,x.id); issues++; continue; }
      for (const k of new Set([...Object.keys(a),...Object.keys(x)])) {
        if(k==='reference'||k==='verse') continue;
        if(JSON.stringify(a[k])!==JSON.stringify(x[k])) { console.log('CHANGED FIELD',g,x.id,k); issues++; }
      }
    }
    if(om.size!==n[g].length){ console.log('COUNT DIFF',g,om.size,n[g].length); issues++; }
  }
  console.log('non-reference/verse differences:',issues);
})();
